/** An amount with at most two decimals, more than 0.00. */
const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;
/** A date typed as yyyy-mm-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;
